INSERT INTO `kjun4_messages` (`message_id`, `user_id_from`, `user_id_to`, `folder_id`, `date_time`, `state`, `priority`, `subject`, `message`) VALUES
(60, 42, 42, 0, '2018-11-02 19:00:13', 0, 0, 'nnbvc Заказ звонка с сайта Бытовки металлические и деревянные Производство Цены от 32000 руб.  от nnbvc', '<!DOCTYPE html>\n<html>\n<head><meta http-equiv="Content-Type" content="text/html; charset=utf-8"></head>\n<body><div dir="ltr"><div style="width: 100%; padding: 24px 0 24px 0; background-color: #fafafa; font-family: ''Helvetica Neue'', Helvetica, Arial, sans-serif;">\r\n	<div style="width: 90%; max-width: 680px; min-width: 280px; border: 1px solid #dddddd; background-color: #ffffff; box-shadow: 0 4px 8px rgba(192, 192, 192, 0.9); margin: auto;">\r\n		<div style="color: #505050; font-size: 13px; padding: 24px;">\r\n			<div style="font-size: 30px; line-height: 34px; border-bottom: 1px solid #dddddd; margin-bottom: 32px; padding-bottom: 8px;">Бытовки металлические и деревянные Производство Цены от 32000 руб. </div>\r\n			<dl>\n<dt style="background-color: #eeeeee; padding: 4px; font-weight: bold;">Имя</dt>\n<dd style="margin: 4px 4px 16px 4px;">nnbvc</dd>\n<dt style="background-color: #eeeeee; padding: 4px; font-weight: bold;">Телефон</dt>\n<dd style="margin: 4px 4px 16px 4px;">89264534722</dd>\n<dt style="background-color: #eeeeee; padding: 4px; font-weight: bold;">Site Name</dt>\n<dd style="margin: 4px 4px 16px 4px;">Бытовки металлические и деревянные Производство Цены от 32000 руб. </dd>\n<dt style="background-color: #eeeeee; padding: 4px; font-weight: bold;">Contact Page URL</dt>\n<dd style="margin: 4px 4px 16px 4px;"><a href="https://doma-bitovki.ru/zakazat-obratnyj-zvonok" class="field-table-href">Для вас опция заказать обратный звонок. Звоните и заказывайте бытовки и блок-контейнеры.</a></dd>\n<dt style="background-color: #eeeeee; padding: 4px; font-weight: bold;">Client operating system</dt>\n<dd style="margin: 4px 4px 16px 4px;">Windows</dd>\n<dt style="background-color: #eeeeee; padding: 4px; font-weight: bold;">Client web browser</dt>\n<dd style="margin: 4px 4px 16px 4px;">Chrome 70</dd>\n</dl>\r\n			<div style="border-top: 1px solid #dddddd; margin-top: 32px; padding-top: 8px; font-size: 12px; font-style: italic; color: #707070;">© Бытовки металлические и деревянные Производство Цены от 32000 руб. </div>\r\n		</div>\r\n	</div>\r\n</div></div></body>\n</html>\n');
