(3, 0, 0, 'Фотогалерея', '', 'fotogalereya', '', '', '', '<p style="text-align: left;">&nbsp; <span style="font-size: 14pt;">&nbsp;<strong>Бытовки фото</strong></span></p>\r\n<p style="text-align: left;">&nbsp;</p>\r\n<p style="text-align: left;">&nbsp; &nbsp; &nbsp; &nbsp; Бытовки, фото которых представлены на этой странице, собственного производства.&nbsp;Для просмотра галереи изображений, кликните по понравившейся категории. Выберите заинтересовавшую Вас фотографию и кликните по ней.</p>\r\n<p style="text-align: left;">&nbsp;</p>\r\n<p>&nbsp;</p>', '2012-02-29 00:00:00', 1, 1, 0, '0000-00-00 00:00:00', NULL, 3, 1, 0, 32326, '0', '0', '0', '', '', '', 0, '', '', '', '', '', 0, '', NULL, '', 'Бытовки. Фото бытовок. Бытовки металлические и деревянные.', NULL, '*', 0),
(4, 0, -1, 'Нижнее меню', '', 'nizhnee-menyu', '', '', '', '<p>  </p>', '2012-03-01 09:35:45', 1, 1, 0, '0000-00-00 00:00:00', NULL, 4, 1, 0, 125, '0', '0', '0', '', '', '', 0, '', '', '', '', '', 0, '', NULL, '', '', NULL, '*', 0),
(43, 3, 0, 'Внутренняя отделка бытовки', '', 'vnutrennyaya-otdelka-bytovki', '', '', '', '', '2018-04-08 13:08:18', 1, 1, 0, '0000-00-00 00:00:00', NULL, 27, 1, 0, 206, '0', '0', '0', 'Bitovki-vnutri', '', '', 0, '', '', '', '', '', 0, '', NULL, '', '', NULL, '*', 0),
(32, 3, 0, 'Бытовки ПРЕМИУМ', '', 'bytovki-premium', '', '', '', '', '2018-01-14 20:49:28', 1, 1, 0, '0000-00-00 00:00:00', NULL, 24, 1, 0, 361, '0', '0', '0', 'Bitovki-premium', '', '', 0, '', '', '', '', '', 0, '', NULL, '', '', NULL, '*', 0),
(33, 3, 0, 'Домики дачные', '', 'domiki', '', '', '', '<div>&nbsp; &nbsp;<span style="font-size: 12pt;"><strong>Садовые домики дачные от производителя за 10 дней.</strong></span></div>\r\n<div>Дачный домик на вашем участкеэ</div>\r\n<div>&nbsp;</div>\r\n<div>&nbsp;</div>', '2018-01-14 00:00:00', 1, 1, 0, '0000-00-00 00:00:00', NULL, 25, 1, 0, 445, '0', '0', '0', 'Domiki', '', '', 0, '', '', '', '', '', 0, '', NULL, '', '', NULL, '*', 0),
